-- T010 — the administrator pass of Phase 1 (specs/002-identity/data-model.md §1, §2, §5; ERD §12,
-- §15). Generated by `prisma migrate diff --from-config-datasource --to-schema prisma/schema
-- --script` against a database holding every migration before it, then extended by hand below
-- the marker.
--
-- What it lands: `admin_sessions` (R-SEC-8, R-107) and `admin_recovery_codes` (ADR 0019 D3); the
-- `admin_users` columns of FR-170 to FR-174: `password_hash` nullable from invite until the password
-- is set, `mfa_last_accepted_step` (RFC 6238 §5.2), `mfa_enrolled_at`, the lockout pair
-- `failed_sign_in_count` and `locked_until_at`, and the invite, password-set, disabled and last
-- sign-in instants; the uniques of rule 25. The seeded administrator keeps its hash and its
-- `is_active = true` with `disabled_at` null, so rules 30 and 31 hold on arrival.
-- AlterTable
ALTER TABLE "admin_users" ADD COLUMN     "disabled_at" TIMESTAMPTZ(6),
ADD COLUMN     "failed_sign_in_count" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "invited_at" TIMESTAMPTZ(6),
ADD COLUMN     "invited_by_admin_id" UUID,
ADD COLUMN     "last_sign_in_at" TIMESTAMPTZ(6),
ADD COLUMN     "locked_until_at" TIMESTAMPTZ(6),
ADD COLUMN     "mfa_enrolled_at" TIMESTAMPTZ(6),
ADD COLUMN     "mfa_last_accepted_step" BIGINT,
ADD COLUMN     "password_set_at" TIMESTAMPTZ(6),
ALTER COLUMN "password_hash" DROP NOT NULL;

-- CreateTable
CREATE TABLE "admin_sessions" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "admin_id" UUID NOT NULL,
    "token_hash" TEXT NOT NULL,
    "mfa_verified_at" TIMESTAMPTZ(6),
    "issued_at" TIMESTAMPTZ(6) NOT NULL,
    "last_seen_at" TIMESTAMPTZ(6) NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "revoked_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,

    CONSTRAINT "admin_sessions_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "admin_recovery_codes" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "admin_id" UUID NOT NULL,
    "code_hash" TEXT NOT NULL,
    "used_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "admin_recovery_codes_pkey" PRIMARY KEY ("id")
);

