ALTER TABLE "admin_users" ADD CONSTRAINT "admin_users_invited_by_admin_id_fkey" FOREIGN KEY ("invited_by_admin_id") REFERENCES "admin_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "admin_sessions" ADD CONSTRAINT "admin_sessions_admin_id_fkey" FOREIGN KEY ("admin_id") REFERENCES "admin_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "admin_recovery_codes" ADD CONSTRAINT "admin_recovery_codes_admin_id_fkey" FOREIGN KEY ("admin_id") REFERENCES "admin_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written: what the schema language cannot say (data-model.md §5, ERD §15).

-- Rule 30: a lock never exists without the count that caused it.
ALTER TABLE "admin_users" ADD CONSTRAINT "admin_users_lock_needs_count_check"
    CHECK ("locked_until_at" IS NULL OR "failed_sign_in_count" > 0);

-- Rule 31: `is_active` cannot drift from its source, `disabled_at`.
ALTER TABLE "admin_users" ADD CONSTRAINT "admin_users_is_active_check"
    CHECK ("is_active" = ("disabled_at" IS NULL));

-- The two tables keep DELETE for the application role: a session is destroyed on sign-out, and
-- regenerating the recovery codes deletes the unused ones (data-model.md §5). The default
-- privileges grant it; nothing here revokes it.
